using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading.Tasks;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using CrossTheLine;
public static class RenderedExceptionReview {
 public static async Task<string> Run(){var g=UnityEngine.Object.FindAnyObjectByType<JourneyGame>();var w=g.GetComponent<JourneyContinuousWorld>();var f=BindingFlags.Instance|BindingFlags.NonPublic;void Call(string n,params object[] a)=>typeof(JourneyGame).GetMethod(n,f).Invoke(g,a);bool saving=JourneySceneFlow.TestWithoutSaving;SpriteRenderer body=null;Vector3 v=Vector3.zero;string alternatives="";Action<ScriptableRenderContext,Camera> cb=(context,c)=>{if(c!=g.journeyCamera||!body)return;v=c.WorldToViewportPoint(body.bounds.center);alternatives=string.Join(";",g.GetComponentsInChildren<SpriteRenderer>().Where(r=>r.enabled&&r.sprite&&r.color.a>.1f&&r.bounds.size.y<4).Where(r=>{var p=c.WorldToViewportPoint(r.bounds.center);return p.x>0&&p.x<1&&p.y>0&&p.y<1&&p.z>0;}).Select(r=>r.name+"/"+r.sprite.name).Take(25));};var rows=new List<string>{"chapter\tstep\tmode\tavatarEnabled\tviewport\tvisibleCast"};int[][] cases={new[]{12,4},new[]{13,2},new[]{13,3},new[]{15,1},new[]{15,5},new[]{15,6},new[]{15,7},new[]{15,8},new[]{16,1},new[]{16,2},new[]{16,3}};
 try{JourneySceneFlow.TestWithoutSaving=true;Time.timeScale=1;RenderPipelineManager.beginCameraRendering+=cb;foreach(var item in cases){w.Normalize();Call("ClearStoryPanels");typeof(JourneyGame).GetField("save",f).SetValue(g,new JourneySave{chapter=item[0],step=item[1],unlocked=26});typeof(JourneyGame).GetField("started",f).SetValue(g,true);Call("CloseMenu");Call("LoadWorld",false);body=g.PlayerRoot.GetComponentInChildren<SpriteRenderer>(true);float end=Time.realtimeSinceStartup+1.6f;while(Time.realtimeSinceStartup<end)await Task.Yield();rows.Add($"{item[0]+1}\t{item[1]}\t{g.Mode}\t{body.enabled}\t{v}\t{alternatives}");ScreenCapture.CaptureScreenshot(Path.GetFullPath("Docs/QA/RenderedChapters/Review-"+(item[0]+1).ToString("00")+"-"+item[1]+".png"));int frame=Time.frameCount;while(Time.frameCount<frame+3)await Task.Yield();}File.WriteAllLines("Docs/QA/RenderedChapters/ExceptionReview.tsv",rows);return string.Join("\n",rows.Select(r=>r.Length>180?r.Substring(0,180):r));}finally{RenderPipelineManager.beginCameraRendering-=cb;JourneySceneFlow.TestWithoutSaving=saving;Time.timeScale=1;}}
}
